import * as am5 from '@amcharts/amcharts5';

export class QPieChartDefaultTheme extends am5.Theme {
  textColor: am5.Color | null = null;
  tooltipBackgroundColor: am5.Color | null = null;
  tooltipTextColor: am5.Color | null = null;

  private _colors: am5.Color[] = [];

  update(): void {
    this._setThemeColors();
    this.setupDefaultRules();
  }

  protected override setupDefaultRules(): void {
    this.rule('ColorSet').setAll({
      colors: this._colors,
      reuse: false, // use 'false' to auto-generate colors when it runs out of colors
      passOptions: {
        lightness: 0.05,
        hue: 0,
      },
    });
  }

  private _setThemeColors(): void {
    const chartContainerStyles = getComputedStyle(this._root.dom);
    const colorTokens = [
      'ads-color-body-400',
      'ads-color-body-500',
      'ads-color-body-600',
      'ads-color-body-700',
      'ads-color-primary-500',
      'ads-color-primary-400',
      'ads-color-primary-300',
      'ads-color-primary-200',
    ];

    colorTokens.forEach((token) => {
      const colorValue = chartContainerStyles.getPropertyValue(`--${token}`);
      this._colors.push(am5.color(colorValue.trim()));
    });

    const textColorToken = 'ads-color-body-contrast-100';
    const tooltipBgColorToken = 'ads-color-body-700';
    const tooltipTextColorToken = 'ads-color-body-100';

    this.textColor = am5.color(chartContainerStyles.getPropertyValue(`--${textColorToken}`).trim());
    this.tooltipBackgroundColor = am5.color(
      chartContainerStyles.getPropertyValue(`--${tooltipBgColorToken}`).trim(),
    );
    this.tooltipTextColor = am5.color(
      chartContainerStyles.getPropertyValue(`--${tooltipTextColorToken}`).trim(),
    );
  }
}
