import * as am5 from '@amcharts/amcharts5';
import * as am5percent from '@amcharts/amcharts5/percent';
import am5themes_Animated from '@amcharts/amcharts5/themes/Animated';
import { NgClass, NgTemplateOutlet } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ContentChild,
  DOCUMENT,
  ElementRef,
  HostBinding,
  Input,
  NgZone,
  OnChanges,
  OnDestroy,
  SimpleChanges,
  TemplateRef,
  ViewChild,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import {
  QDestroyService,
  QSharedMutationObserverService,
} from '@questrade/allspark-angular-components/core/services';
import { takeUntil } from 'rxjs';
import { QPieChartDefaultTheme } from './themes/pie-chart-default-theme';
import { QPieChartDataItem } from './types/pie-chart-data-item.interface';
import { QPieChartLayout } from './types/pie-chart-layout.type';
import { QPieChartSize } from './types/pie-chart-size.type';
import { QPieChartTextSet } from './types/pie-chart-text-set.interface';
import { QPieChartVariant } from './types/pie-chart-variant.type';

interface SizeThicknessMap {
  sm: number;
  md: number;
  lg: number;
}

@Component({
  selector: 'q-pie-chart',
  templateUrl: './pie-chart.component.html',
  styleUrls: ['./pie-chart.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [NgClass, NgTemplateOutlet],
  providers: [QDestroyService],
})
export class QPieChartComponent implements OnChanges, AfterViewInit, OnDestroy {
  @Input() legendLabelText = '{category}:';
  @Input() legendValueText = '{value}';
  @Input() labelText = '{category}: {value}';
  @Input() colors: string[] = [];
  @Input() license = '';
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-pie-chart';

  @Input() get yOffset(): number {
    return this._yOffset;
  }
  set yOffset(value: number) {
    this._yOffset = value;

    if (this._root) this._initChart();
  }

  @Input() get legendColumns(): number {
    return this._legendColumns;
  }
  set legendColumns(value: number) {
    this._legendColumns = value;

    if (this._root) this._initChart();
  }

  @Input() get showLegend(): boolean {
    return this._showLegend;
  }
  set showLegend(value: boolean) {
    this._showLegend = value;

    if (!value && this._rootInnerContainer) {
      this._rootInnerContainer.children.removeValue(this._legend);
      this._setRootHeight();
    } else if (this._root) {
      this._setLegend();
    }
  }

  @Input() get tooltipText(): string {
    return this._tooltipText;
  }
  set tooltipText(value: string) {
    this._tooltipText = value;
    if (this._root) this._initChart();
  }

  @Input() get layout(): QPieChartLayout {
    return this._layout;
  }
  set layout(value: QPieChartLayout) {
    this._layout = value;
    if (this._root) this._initChart();
  }

  @Input() get disableHoverAnimation(): boolean {
    return this._disableHoverAnimation;
  }
  set disableHoverAnimation(value: boolean) {
    this._disableHoverAnimation = value;

    if (this._root) this._initChart();
  }

  @Input() get showLabels(): boolean {
    return this._showLabels;
  }
  set showLabels(value: boolean) {
    this._showLabels = value;
    this._series?.labels.template.set('forceHidden', !this._showLabels);
    this._series?.ticks.template.set('forceHidden', !this._showLabels);
  }

  @Input() get reverseDataSet(): boolean {
    return this._reverseDataSet;
  }
  set reverseDataSet(value: boolean) {
    this._reverseDataSet = value;
    this._cdr.detectChanges();
    this._setLabels();
  }

  @Input() get internalSectionTextData(): QPieChartTextSet[] {
    return this._internalSectionTextData;
  }
  set internalSectionTextData(value: QPieChartTextSet[]) {
    this._internalSectionTextData = value;
    this._cdr.detectChanges();
    this._setLabels();
  }

  @Input() get type(): QPieChartVariant {
    return this._type;
  }
  set type(value: QPieChartVariant) {
    this._type = value;
    this._cdr.detectChanges();
    this._chart?.set('innerRadius', this.type !== 'solid' ? this._getDonutRadius() : undefined);
    this._setLabels();
  }

  @Input() get size(): QPieChartSize {
    return this._size;
  }
  set size(value: QPieChartSize) {
    this._size = value;
    this._cdr.detectChanges();
    if (this._root) this._initChart();
  }

  @Input() get data(): QPieChartDataItem[] {
    return this._data;
  }
  set data(value: QPieChartDataItem[]) {
    this._data = value;

    this._series?.data.setAll(this._data);
    if (this._legend) this._setLegend();
  }

  @ContentChild('internalSection') internalSectionTemplate!: TemplateRef<HTMLElement>;

  @ViewChild('internalSection') internalSectionEl!: ElementRef;
  @ViewChild('chartContainer') _chartContainer!: ElementRef<HTMLElement>;

  _root!: am5.Root;
  _rootInnerContainer!: am5.Container;
  _chart!: am5percent.PieChart;
  _series!: am5percent.PieSeries;
  _legend!: am5.Legend;
  _label!: am5.Label;
  _isDarkTheme = false;
  private _defaultTheme: QPieChartDefaultTheme | null = null;

  private _yOffset = 15;
  private _legendColumns = 3;
  private _showLegend = true;
  private _tooltipText = '{valuePercentTotal}%';
  private _layout: QPieChartLayout = 'vertical';
  private _disableHoverAnimation = false;
  private _showLabels = false;
  private _reverseDataSet = false;
  private _internalSectionTextData: QPieChartTextSet[] = [];
  private _type: QPieChartVariant = 'donut-thin';
  private _size: QPieChartSize = 'lg';
  private _data: QPieChartDataItem[] = [];
  private _sizeMap = new Map<QPieChartSize, number>([
    ['sm', 88],
    ['md', 192],
    ['lg', 280],
  ]);
  private _thicknessMap = new Map<QPieChartVariant, SizeThicknessMap>([
    ['donut-thin', { sm: 8, md: 12, lg: 16 }],
    ['donut-medium', { sm: 16, md: 20, lg: 24 }],
    ['donut-bold', { sm: 24, md: 32, lg: 40 }],
    ['donut-extra-bold', { sm: 32, md: 48, lg: 56 }],
  ]);
  private readonly _document = inject(DOCUMENT);
  private readonly _ngZone = inject(NgZone);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _sharedMutationObserverService = inject(QSharedMutationObserverService);

  constructor() {
    this._subscribeToThemeChanges();
  }

  ngOnChanges(changes: SimpleChanges): void {
    const { license } = changes;

    if (license?.currentValue) {
      this._addLicenseKey();
    }
  }

  ngAfterViewInit(): void {
    this._initChart();
  }

  ngOnDestroy(): void {
    this._ngZone.runOutsideAngular(() => {
      this._root?.dispose();
    });
  }

  _hideFirstTextDataSetLabel(): boolean {
    return this.size === 'sm';
  }

  _hideFirstTextDataSet(): boolean {
    return this.size === 'sm' && (this.type === 'donut-bold' || this.type === 'donut-extra-bold');
  }

  _hideSecondTextDataSet(): boolean {
    return this.size === 'sm' || (this.size === 'md' && this.type === 'donut-extra-bold');
  }

  _getTextValueCSSClasses(): string {
    if (this.size === 'md' && this.type === 'donut-extra-bold') {
      return 'medium-extra-bold';
    } else if (this.size === 'md') {
      return 'medium-thin';
    } else if (this.size === 'lg' && this.type === 'donut-extra-bold') {
      return 'large-extra-bold';
    } else if (this.size === 'lg') {
      return 'large-thin';
    } else return 'small-thin';
  }

  get _licenses(): string[] {
    return am5.registry.licenses as string[];
  }

  private _subscribeToThemeChanges(): void {
    this._isDarkTheme = this._document.body.classList.contains('dark-theme');

    this._sharedMutationObserverService
      .observe(this._document.body, { attributes: true })
      ?.pipe(takeUntil(this._destroy$))
      .subscribe((mutations: MutationRecord[]) => {
        mutations.forEach((mutation: MutationRecord) => {
          const bodyEl = mutation.target as HTMLElement;

          if (mutation.attributeName === 'class') {
            const isDarkTheme = bodyEl?.classList?.contains('dark-theme');

            if (this._isDarkTheme !== isDarkTheme) {
              this._isDarkTheme = isDarkTheme;
              this._initChart();
            }
          }
        });
      });
  }

  private _initChart(): void {
    this._ngZone.runOutsideAngular(() => {
      if (!this._root) {
        this._root = am5.Root.new(this._chartContainer.nativeElement);
      }

      this._defaultTheme = QPieChartDefaultTheme.new(this._root);
      this._defaultTheme.update();

      this._root.setThemes([am5themes_Animated.new(this._root), this._defaultTheme]);

      this._setChart();
      this._setSeries();
      this._setLabels();

      if (this.showLegend) {
        this._setLegend();
      }
    });
  }

  private _setChart(): void {
    if (this._root) {
      this._root.container.children.clear();

      this._rootInnerContainer = this._root.container.children.push(
        am5.Container.new(this._root, {
          centerX: am5.p50,
          x: am5.p50,
          layout:
            this.layout === 'horizontal' ? this._root.horizontalLayout : this._root.verticalLayout,
          y: this.yOffset,
        }),
      );

      if (this.layout === 'vertical') {
        this._rootInnerContainer.setAll({
          width: am5.p100,
        });
      }

      this._chart = this._rootInnerContainer.children.push(
        am5percent.PieChart.new(this._root, {
          radius: am5.p100,
          height: this._sizeMap.get(this.size) || null,
        }),
      );

      this._chart?.set('innerRadius', this.type !== 'solid' ? this._getDonutRadius() : undefined);

      if (this.layout === 'horizontal') {
        this._chart.setAll({ width: (this._sizeMap.get(this.size) || 0) + 15, x: 15 });
      }
    }
  }

  private _setSeries(): void {
    if (this._chart) {
      this._chart.series.clear();
      this._series = this._chart.series.push(
        am5percent.PieSeries.new(this._root, {
          name: 'QPieSeries',
          categoryField: 'category',
          valueField: 'value',
          fillField: 'color',
          legendLabelText: this.legendLabelText,
          legendValueText: this.legendValueText,
        }),
      );

      this._setSeriesTooltip();

      this._setSeriesCustomColors();

      this._setSeriesSlices();

      this._series.events.on('datavalidated', () => {
        this._setRootHeight();
      });

      if (this.data.length) {
        this._series.data.setAll(this.data);
        this._series.appear().finally(() => void 0);
      }
    }
  }

  private _setSeriesTooltip(): void {
    const tooltip = am5.Tooltip.new(this._root, {
      getFillFromSprite: false,
      autoTextColor: false,
      pointerOrientation: 'left',
      labelHTML: `
                <span class="q-pie-chart-tooltip">
                    ${this.tooltipText}
                </span>`,
      paddingBottom: 8,
      paddingTop: 8,
      paddingLeft: 12,
      paddingRight: 12,
    });

    if (
      this._defaultTheme &&
      this._defaultTheme.tooltipBackgroundColor &&
      this._defaultTheme.tooltipTextColor
    ) {
      tooltip.get('background')?.setAll({
        fill: this._defaultTheme.tooltipBackgroundColor,
        fillOpacity: 1,
        strokeOpacity: 0,
      });

      tooltip.label.setAll({
        fill: this._defaultTheme.tooltipTextColor,
      });
    }

    this._series?.set('tooltip', tooltip);
  }

  private _setSeriesCustomColors(): void {
    if (this.colors.length) {
      this._series.set(
        'colors',
        am5.ColorSet.new(this._root, {
          colors: [...this.colors.map((color) => am5.color(color))],
          reuse: false,
          passOptions: {
            lightness: 0.15,
            hue: 0.8,
          },
        }),
      );
    }
  }

  private _setSeriesSlices(): void {
    // disable slice shift animation on click + add stroke around it
    this._series.slices.template.setAll({
      toggleKey: 'none',
      stroke: am5.color(this._isDarkTheme ? '#111317' : '#fff'),
    });

    if (this.disableHoverAnimation) {
      // disable default scaling animations on hover
      this._series.slices.template.states.create('hover', {
        scale: 1,
        shiftRadius: 0,
      });
    }

    if (this._defaultTheme && this._defaultTheme.textColor) {
      this._series.labels.template.setAll({
        text: this.labelText,
        fill: this._defaultTheme.textColor,
      });

      this._series.ticks.template.setAll({
        stroke: this._defaultTheme.textColor,
      });
    }

    if (!this.showLabels) {
      // remove labels
      this._series.labels.template.set('forceHidden', true);
      // remove lines under labels
      this._series.ticks.template.set('forceHidden', true);
    }
  }

  private _setLegend(): void {
    this._rootInnerContainer.children.removeValue(this._legend);
    this._legend = this._rootInnerContainer.children.push(
      am5.Legend.new(this._root, {
        layout: am5.GridLayout.new(this._root, {
          maxColumns: this.legendColumns,
          fixedWidthGrid: true,
        }),
        visible: this.showLegend,
      }),
    );

    if (this.layout === 'vertical') {
      this._legend.setAll({
        x: am5.p50,
        centerX: am5.p50,
        marginTop: 12,
        dx: 10,
      });
    } else if (this.layout === 'horizontal') {
      this._legend.setAll({
        y: am5.percent(50),
        centerY: am5.percent(50),
      });
      this._legend.itemContainers.template.setAll({
        marginLeft: 32,
      });
    }

    this._setLegendItems();

    this._legend.data.setAll(this._series.dataItems);

    this._legend.events.on('boundschanged', () => {
      this._setRootHeight();
    });
  }

  private _setLegendItems(): void {
    this._legend.itemContainers.template.setAll({
      height: 22,
      marginTop: 6,
      marginBottom: 6,
    });

    this._legend.itemContainers.template.setup = (item: am5.Sprite): void => {
      item.events.disableType('pointerover');
      item.events.disableType('click');
    };

    if (this._defaultTheme && this._defaultTheme.textColor) {
      this._legend.labels.template.setAll({
        oversizedBehavior: 'truncate',
        fill: this._defaultTheme.textColor,
      });

      this._legend.valueLabels.template.setAll({
        fill: this._defaultTheme.textColor,
      });
    }

    this._legend.markers.template.setAll({
      width: 12,
      height: 12,
    });

    this._legend.markerRectangles.template.setAll({
      cornerRadiusTL: 10,
      cornerRadiusTR: 10,
      cornerRadiusBL: 10,
      cornerRadiusBR: 10,
    });
  }

  private _setLabels(): void {
    if (this._series && this.internalSectionEl) {
      this._series.children.removeValue(this._label);
      this._label?.dispose();

      if (this._type !== 'solid')
        this._label = this._series.children.push(
          am5.Label.new(this._root, {
            html: this.internalSectionEl.nativeElement.innerHTML as string,
            centerX: am5.percent(50),
            centerY: am5.percent(50),
          }),
        );
    }
  }

  private _setRootHeight(): void {
    const chartHeight = this._sizeMap.get(this.size) || 1;
    const legendHeight = this._showLegend ? this._legend.height() : 0;
    const height =
      this._layout === 'vertical'
        ? chartHeight + legendHeight + this.yOffset * 2
        : Math.max(chartHeight, legendHeight) + this.yOffset * 2;

    this._root.dom.style.height = `${height}px`;
  }

  private _getDonutRadius(): am5.Percent {
    const thicknessType = this._thicknessMap.get(this.type);
    const mapSize = this._sizeMap.get(this.size);
    if (thicknessType && mapSize) {
      const thickness = thicknessType[this.size];
      return am5.percent(100 - (thickness * 2 * 100) / mapSize);
    } else {
      return am5.p100;
    }
  }

  private _addLicenseKey(): void {
    if (!this._licenses.includes(this.license)) {
      am5.addLicense(this.license);
    }
  }
}
